import math

def comb(n, k):
    if k < 0 or k > n:
        return 0
    k = min(k, n - k)
    if k == 0:
        return 1
    num = 1
    den = 1
    for i in range(1, k + 1):
        num *= (n - k + i)
        den *= i
    return num // den

def enumerate_compositions(total, caps):
    # Enumerate tuples (x_i) with sum=total and 0<=x_i<=caps[i]
    res = []
    x = [0] * len(caps)
    def rec(i, remaining):
        if i == len(caps) - 1:
            val = remaining
            if 0 <= val <= caps[i]:
                x[i] = val
                res.append(tuple(x))
            return
        max_i = min(caps[i], remaining)
        for val in range(0, max_i + 1):
            x[i] = val
            rec(i + 1, remaining - val)
    rec(0, total)
    return res

while True:
    c = rng.randint(3, 5)
    counts = [rng.randint(6, 16) for _ in range(c)]
    N = sum(counts)
    sum_half = sum(n // 2 for n in counts)
    if sum_half < 3:
        continue
    t_upper = min(6, sum_half - 1)
    if t_upper < 2:
