    caps_x = [n // 2 for n in counts]
    Xs = enumerate_compositions(t, caps_x)
    if not Xs:
        continue
    denom = comb(N, t) * comb(N - t, k) * comb(N - t - k, t)
    num = 0
    for x in Xs:
        waysT = 1
        li = []
        for n, xi in zip(counts, x):
            waysT *= comb(n, xi)
            li.append(n - xi)
        Rs = enumerate_compositions(k, li)
        for r in Rs:
            waysR = 1
            mi = []
            for L, ri in zip(li, r):
                waysR *= comb(L, ri)
                mi.append(L - ri)
            waysM = 1
            feasible = True
            for mci, xi in zip(mi, x):
                w = comb(mci, xi)
                if w == 0:
                    feasible = False
                    break
                waysM *= w
            if feasible:
                num += waysT * waysR * waysM
    if num == 0 or num == denom:
        continue
